function dappleOverlay() {
	overlay.background('rgb(249,234,178)');
	overlay.pixelDensity(1);
	overlay.loadPixels();
	for (let x = 0; x < floor(overlay.width); x += 1) {
		for (let y = 0; y < floor(overlay.height); y += (Math.max(0.001, Math.abs(floor(random(1, 4)) || 1)))) {
			var index = (x + y * overlay.width) * 4;
			let avalue = map(noise(x / overlay.width, y), 0, 1, 0, 32);
			overlay.pixels[index + 3] = avalue;
		}
	}
	overlay.updatePixels();
}

